low: visible on th/td elements.","tree":{"sha":"880363a02fa79aa03a1f4b49ede7dc77f82d2905","url":"https://api.github.com/repos/celinepyun-ops/gallop-ai/git/trees/880363a02fa79aa03a1f4b49ede7dc77f82d2905"},"url":"https://api.github.com/repos/celinepyun-ops/gallop-ai/git/commits/d1d4acf086902c7c29efe5c093a280ae90d71000","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/262822201?v=4","events_url":"https://api.github.com/users/celinepyun-ops/events{/privacy}","followers_url":"https://api.github.com/users/celinepyun-ops/followers","following_url":"https://api.github.com/users/celinepyun-ops/following{/other_user}","gists_url":"https://api.github.com/users/celinepyun-ops/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/celinepyun-ops","id":262822201,"login":"celinepyun-ops","node_id":"U_kgDOD6pZOQ","organizations_url":"https://api.github.com/users/celinepyun-ops/orgs","received_events_url":"https://api.github.com/users/celinepyun-ops/received_events","repos_url":"https://api.github.com/users/celinepyun-ops/repos","site_admin":false,"starred_url":"https://api.github.com/users/celinepyun-ops/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/celinepyun-ops/subscriptions","type":"User","url":"https://api.github.com/users/celinepyun-ops","user_view_type":"public"},"html_url":"https://github.com/celinepyun-ops/gallop-ai/commit/d1d4acf086902c7c29efe5c093a280ae90d71000","node_id":"C_kwDORfkAq9oAKGQxZDRhY2YwODY5MDJjN2MyOWVmZTVjMDkzYTI4MGFlOTBkNzEwMDA","parents":[{"html_url":"https://github.com/celinepyun-ops/gallop-ai/commit/10dba09d77beb3e6733d44e7dc797b5477f68985","sha":"10dba09d77beb3e6733d44e7dc797b5477f68985","url":"https://api.github.com/repos/celinepyun-ops/gallop-ai/commits/10dba09d77beb3e6733d44e7dc797b5477f68985"}],"sha":"d1d4acf086902c7c29efe5c093a280ae90d71000","url":"https://api.github.com/repos/celinepyun-o